import * as T from './vendor/three.module.js';
const loader=new T.TextureLoader();
export async function texture(name){const t=await loader.loadAsync('./assets/'+name);t.colorSpace=T.SRGBColorSpace;return t}
// Extract views at runtime, removing only neutral background connected to image edges.
// Original reference files remain unchanged.
export async function views(name,regions){const source=await texture(name),im=source.image;return regions.map(([x,y,w,h])=>{const c=document.createElement('canvas');c.width=Math.round(w*im.width);c.height=Math.round(h*im.height);const ctx=c.getContext('2d');ctx.drawImage(im,x*im.width,y*im.height,w*im.width,h*im.height,0,0,c.width,c.height);const d=ctx.getImageData(0,0,c.width,c.height),a=d.data,N=c.width*c.height,seen=new Uint8Array(N),q=new Int32Array(N);let head=0,tail=0;function add(i){if(i<0||i>=N||seen[i])return;seen[i]=1;const k=i*4,r=a[k],g=a[k+1],b=a[k+2];if(Math.max(r,g,b)-Math.min(r,g,b)<6&&r>45&&r<185){q[tail++]=i;a[k+3]=0}}for(let x=0;x<c.width;x++){add(x);add(N-1-x)}for(let y=0;y<c.height;y++){add(y*c.width);add(y*c.width+c.width-1)}while(head<tail){const i=q[head++];if(i%c.width)add(i-1);if(i%c.width<c.width-1)add(i+1);add(i-c.width);add(i+c.width)}ctx.putImageData(d,0,0);const t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;return {map:t,aspect:c.width/c.height}})}
export function actor(scene,maps,x,z,height,heading=0){const g=new T.Group();g.position.set(x,0,z);scene.add(g);const material=new T.MeshBasicMaterial({map:maps[0].map,transparent:true,alphaTest:.45,side:T.DoubleSide,color:0xb7c7d4});const plane=new T.Mesh(new T.PlaneGeometry(1,1),material);g.add(plane);return {g,plane,maps,height,heading,x,z,update(camera){const a=Math.atan2(camera.position.x-g.position.x,camera.position.z-g.position.z);const delta=Math.atan2(Math.sin(a-this.heading),Math.cos(a-this.heading));let index=Math.abs(delta)<.75?0:Math.abs(delta)>2.35?2:1;plane.material.map=maps[index].map;plane.scale.set(height*maps[index].aspect*(index===1&&delta<0?-1:1),height,1);plane.position.y=height/2;plane.rotation.y=a}}}

